raph","content":[{"type":"text","text":"That''s amazing / cool"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"😴"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"I''m tired / boring"}]}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অংশ ৩ — বাস্তব Chat Dialogue"}]},{"type":"heading","attrs":{"level":4},"content":[{"type":"text","text":"৩.১ বন্ধুর সাথে চ্যাট"}]},{"type":"paragraph","content":[{"type":"text","text":"Rahim: hey! wyd rn?  —  এই! এখন কী করছিস?"}]},{"type":"paragraph","content":[{"type":"text","text":"You: nm, just chilling. u?  —  কিছু না, রিল্যাক্স করছি। তুই?"}]},{"type":"paragraph","content":[{"type":"text","text":"Rahim: studying for tomorrow''s exam 😅  —  আগামীকালের পরীক্ষার জন্য পড়ছি"}]},{"type":"paragraph","content":[{"type":"text","text":"You: oh no, gud luck! lmk if u need help  —  ওহ, শুভকামনা! সাহায্য লাগলে জানাস"}]},{"type":"paragraph","content":[{"type":"text","text":"Rahim: thx! btw are u free this weekend?  —  ধন্যবাদ! আচ্ছা, এই সপ্তাহান্তে ফ্রি আছিস?"}]},{"type":"paragraph","content":[{"type":"text","text":"You: yeah should be. lets plan smth  —  হ্যাঁ থাকব। কিছু একটা প্ল্যান করি"}]},{"type":"paragraph","content":[{"type":"text","text":"Rahim: sounds gr8, ttyl  —  ভালো শোনাচ্ছে, পরে কথা হবে"}]},{"type":"heading","attrs":{"level":4},"content":[{"type":"text","text":"৩.২ গ্রুপ প্রজেক্ট নিয়ে"}]},{"type":"paragraph","content":[{"type":"text","text":"You: hey guys, when is our project due?  —  এই, আমাদের প্রজেক্ট কবে জমা?"}]},{"type":"paragraph","content":[{"type":"text","text":"Karim: friday i think, lemme check  —  শুক্রবার মনে হয়, একটু চেক করি"}]},{"type":"paragraph","content":[{"type":"text","text":"Karim: yep, confirmed. friday eod  —  হ্যাঁ, নিশ্চিত। শুক্রবার দিন শেষে"}]},{"type":"paragraph","content":[{"type":"text","text":"You: ok, ill finish my part by tmrw  —  ঠিক আছে, আমি আমার অংশ কাল শেষ করব"}]},{"type":"paragraph","content":[{"type":"text","text":"Sadia: same here, will send it asap  —  আমিও, যত দ্রুত সম্ভব পাঠাব"}]},{"type":"paragraph","content":[{"type":"text","text":"You: perfect, thx everyone 🙏  —  চমৎকার, সবাইকে ধন্যবাদ"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অংশ ৪ — Formal বনাম Informal লেখা"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"পরিস্থিতি"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Informal (বন্ধুকে)"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Formal (শিক্ষক/বসকে)"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"শুরু"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"hey! / hi!"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Dear Sir / Good morning,"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"কেমন আছ"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"what''s up? / how''s it going?"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"I hope you are doing well."}}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"অনুরোধ"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"can u send it?"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Could you please send it?"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"ধন্যবাদ"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"thx / thanks a lot!"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"Thank you very much."}}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"শেষ করা"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"ttyl / gtg"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"Looking forward to your reply."}}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"বানান"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"u, ur, gonna, wanna"}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"you, your, going to, want to"}}]}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"🔑 সহজ নিয়ম শিক্ষক, অফিস, অপরিচিত মানুষ, দরখাস্ত → সবসময় পূর্ণ ও সঠিক ইংরেজি ঘনিষ্ঠ বন্ধু, পরিবার (চ্যাটে) → সংক্ষিপ্ত রূপ চলবে, কিন্তু ভদ্রতা বজায় রেখো"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অংশ ৫ — সোশ্যাল মিডিয়া পোস্ট ও কমেন্ট"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"English"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"বাংলা"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Just finished my exam! Feeling relieved 😊"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"মাত্র পরীক্ষা শেষ করলাম! স্বস্তি লাগছে"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"t