  values (v_part_2, 'Business ও Formal English', 'lesson-33', 'Lesson 33 from English Foundation.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"মিটিং, প্রেজেন্টেশন ও অফিসের ইমেইল"}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"🎯 এই Lesson শেষে তুমি যা পারবে"}]},{"type":"paragraph","content":[{"type":"text","text":"১. অফিসের মিটিংয়ে মতামত দিতে ও আলোচনা করতে পারবে।"}]},{"type":"paragraph","content":[{"type":"text","text":"২. একটা ছোট প্রেজেন্টেশন শুরু ও শেষ করতে পারবে।"}]},{"type":"paragraph","content":[{"type":"text","text":"৩. পেশাদার ইমেইলের ভাষা ব্যবহার করতে পারবে।"}]},{"type":"paragraph","content":[{"type":"text","text":"৪. সহকর্মীর সাথে কাজ নিয়ে যোগাযোগ করতে পারবে।"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অংশ ১ — মিটিংয়ে ব্যবহৃত বাক্য"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"কাজ"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"বাক্য"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"শুরু করা"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Let''s get started. / Shall we begin?"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"আলোচ্যসূচি বলা"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"Today''s agenda includes three items."}}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"মতামত দেওয়া"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"In my opinion, ... / I would suggest that..."}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"একমত হওয়া"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"I agree with that point. / That makes sense."}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"দ্বিমত পোষণ করা"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"I see your point, but... / I''m not sure I agree."}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"থামানো"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Sorry to interrupt, but... / Can I add something?"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"স্পষ্ট করা"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"What I mean is... / To clarify..."}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"সিদ্ধান্ত নেওয়া"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"So, we''ve agreed that... / Let''s finalize this."}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"পরবর্তী পদক্ষেপ"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"The next step is to... / Moving forward..."}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"শেষ করা"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Let''s wrap up. / Thank you all for your time."}]}]}]}]},{"type":"heading","attrs":{"level":4},"content":[{"type":"text","text":"১.১ Dialogue — টিম মিটিং"}]},{"type":"paragraph","content"